begin;
insert into public.ce_course3_resources(id,data) values
('course3_module2_pdf','{"base64": "", "sha256": "895baf065037c9ac82ea55d709b9c9526eb4570338ce68edc80758d6d4637c94", "filename": "CE_HALO_Course3_Module02_Informed_Consent_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module2_questions','[{"module_id": "course_3_module_2", "question_id": "course_3_module_2_q01", "question_number": 1, "stem": "According to AANA Standard 4 and the April 2024 CMS revised interpretive guidance, informed consent for anesthesia is best described as:", "choice_a": "A communication process that includes disclosure, understanding, voluntariness, capacity, and authorization", "choice_b": "A signature witnessed by a circulating nurse before induction", "choice_c": "A verbal agreement that the anesthesia team may proceed", "choice_d": "A signed consent form obtained by the preoperative nurse", "correct_choice": "a", "rationale": "Both AANA Standard 4 and the April 2024 CMS interpretive guidance define informed consent as a process, not the signing of a form. The five core elements are disclosure, understanding, voluntariness, decision-making capacity, and authorization.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q02", "question_number": 2, "stem": "A patient signs the surgical consent form. On arrival to the OR, the patient states, \"No one told me about the anesthesia.\" The CRNA''s most appropriate next action is to:", "choice_a": "Have the circulating nurse re-witness the signature", "choice_b": "Stop and complete the anesthesia consent discussion before proceeding", "choice_c": "Administer midazolam and complete the discussion in the OR", "choice_d": "Proceed with induction because the surgical consent is signed", "correct_choice": "b", "rationale": "A signed surgical consent does not authorize the anesthesia plan. The CRNA should stop and complete the anesthesia consent discussion. Consent must not be obtained after sedating medication has impaired capacity.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q03", "question_number": 3, "stem": "Under the April 2024 CMS revised hospital interpretive guidance, informed consent must disclose all of the following EXCEPT:", "choice_a": "The identity of the practitioner who will perform the procedure", "choice_b": "The participation of medical students, residents, or fellows", "choice_c": "The specific billing code assigned to the procedure", "choice_d": "Consent for a medical student to perform a sensitive examination under anesthesia", "correct_choice": "c", "rationale": "The April 2024 guidance requires disclosure of who will perform the procedure, trainee participation, and explicit consent for sensitive examinations. Billing codes are not part of the consent-disclosure requirement.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q04", "question_number": 4, "stem": "Which AANA Standard specifically addresses informed consent for anesthesia care?", "choice_a": "Standard 2 — Preanesthesia Patient Assessment and Evaluation", "choice_b": "Standard 3 — Plan for Anesthesia Care", "choice_c": "Standard 1 — Patient''s Rights", "choice_d": "Standard 4 — Informed Consent for Anesthesia Care and Related Services", "correct_choice": "d", "rationale": "Standard 4, titled \"Informed Consent for Anesthesia Care and Related Services,\" requires the CRNA to obtain and document, or verify the documentation, that consent has been given for the planned anesthesia care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q05", "question_number": 5, "stem": "Which regulation requires a properly executed informed consent form to be in the patient''s medical record before surgery, except in emergencies?", "choice_a": "42 CFR §482.51(b)(2)", "choice_b": "42 CFR §482.24(c)(4)(v)", "choice_c": "42 CFR §482.13(b)(2)", "choice_d": "42 CFR §482.52", "correct_choice": "a", "rationale": "42 CFR §482.51(b)(2) specifically addresses the requirement for a properly executed informed-consent form for the operation in the medical record before surgery, except in emergencies. §482.52 addresses anesthesia service supervision, not consent forms.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q06", "question_number": 6, "stem": "A circulating nurse witnesses a patient''s signature on the anesthesia consent form. This action:", "choice_a": "Establishes that informed consent was obtained", "choice_b": "Confirms that the correct person signed the form, but does not establish that informed consent was obtained", "choice_c": "Substitutes for the CRNA''s obligation to verify understanding", "choice_d": "Fulfills AANA Standard 4 on behalf of the CRNA", "correct_choice": "b", "rationale": "Witnessing a signature confirms only the identity of the signer. It does not establish that a valid consent discussion occurred. Standard 4 places the consent responsibility on the anesthesia professional.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q07", "question_number": 7, "stem": "A CRNA cares for a Spanish-speaking patient with limited English proficiency. The most appropriate approach to consent is to:", "choice_a": "Use the patient''s adult family member to interpret", "choice_b": "Use written English materials and hand gestures", "choice_c": "Use a qualified medical interpreter and document the interpreter''s identity, language, and service ID", "choice_d": "Proceed and document \"consent obtained\" once the patient signs", "correct_choice": "c", "rationale": "Qualified medical interpreters are the standard for consent with LEP patients. Family members should not be used as primary interpreters whenever a qualified medical interpreter is available. Interpreter identity and service ID should be documented.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q08", "question_number": 8, "stem": "A patient with capacity refuses the only anesthetic technique the CRNA believes is safe. The CRNA should:", "choice_a": "Administer sedation without consent so the case can proceed", "choice_b": "Document \"patient refused\" and cancel the case without further discussion", "choice_c": "Proceed with an anesthetic technique the CRNA believes is unsafe because the patient has autonomy", "choice_d": "Reassess capacity, clarify the refusal, explain risks of refusal, discuss alternatives, and escalate — and not proceed with an unsafe plan", "correct_choice": "d", "rationale": "Informed refusal requires a structured response: reassess capacity, clarify the refusal, explain risks of refusal, discuss alternatives, involve appropriate team members, do not proceed with an unsafe plan, and document. Refusal is not a consent problem to \"work around.\"", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q09", "question_number": 9, "stem": "Which of the following documentation entries best satisfies AANA Standard 4 for a general anesthetic?", "choice_a": "\"Discussed general anesthesia with endotracheal intubation, including sore throat, dental injury, aspiration, PONV, awareness, cardiopulmonary complications, medication reaction, and rare risk of serious injury or death. Alternatives and questions reviewed. Patient verbalized understanding and agreed.\"", "choice_b": "\"Consent form signed pre-op.\"", "choice_c": "\"See surgical consent.\"", "choice_d": "\"Risks explained. Patient consents.\"", "correct_choice": "a", "rationale": "Specific, individualized language identifying the technique and representative material risks satisfies Standard 4 and the CMS 2024 guidance. Vague entries such as \"risks explained\" or references to a surgical consent do not.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q10", "question_number": 10, "stem": "An intraoperative crisis converts a peripheral nerve block with sedation into a general anesthetic. Regarding consent, the CRNA should:", "choice_a": "Rely on the surgical consent alone", "choice_b": "Manage the airway and hemodynamics, then document the clinical rationale for the conversion afterward", "choice_c": "Stop the case to obtain new signed consent", "choice_d": "Have the surgeon obtain new consent while the CRNA manages the airway", "correct_choice": "b", "rationale": "For a material plan change during an emergency, care priorities take precedence. The CRNA should manage the crisis, then document the clinical rationale for the conversion in the anesthesia record.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q11", "question_number": 11, "stem": "AANA Standard 2 relates to informed consent because it requires:", "choice_a": "Disclosure of anesthesia billing codes to the patient", "choice_b": "A signed consent form before surgery", "choice_c": "A preanesthesia evaluation and anesthesia-focused physical assessment that informs individualized risk disclosure", "choice_d": "The CRNA to obtain consent from the surgeon", "correct_choice": "c", "rationale": "Standard 2 requires the CRNA to perform or verify a preanesthesia evaluation and anesthesia-focused physical assessment. This assessment identifies patient-specific risks that must be individualized in the consent discussion required by Standard 4.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q12", "question_number": 12, "stem": "A trauma patient arrives obtunded, hemorrhaging, and unable to consent. No surrogate is reachable. The CRNA proceeds under the emergency exception. The strongest legal protection comes from:", "choice_a": "Having the circulating nurse sign the consent form", "choice_b": "The verbal report from the EMS provider", "choice_c": "Waiting until after the case to notify risk management", "choice_d": "Documenting the emergency condition, efforts to contact a surrogate, inability to obtain consent, and the clinical reason anesthesia could not be delayed", "correct_choice": "d", "rationale": "Emergency-exception protection is strongest when the record documents the emergency, surrogate-contact efforts, inability to obtain consent, and clinical rationale for immediate anesthesia care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q13", "question_number": 13, "stem": "A 16-year-old presents for cesarean delivery. Regarding consent, the CRNA should:", "choice_a": "Follow facility policy and applicable state law regarding pregnant-minor consent and document who provided consent, their authority, capacity, and interpreter use if applicable", "choice_b": "Assume the parents must consent regardless of state law", "choice_c": "Delay the case until legal consultation is obtained", "choice_d": "Assume the minor may consent regardless of state law", "correct_choice": "a", "rationale": "Pregnant-minor consent rules vary by state. The CRNA should document that facility policy and applicable state law were followed, and identify the person providing consent and their authority.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q14", "question_number": 14, "stem": "Under the April 2024 CMS interpretive guidance, consent for a medical student to perform a sensitive examination under anesthesia:", "choice_a": "Is automatically included in consent to the underlying procedure", "choice_b": "Must be obtained explicitly, separate from consent to the underlying procedure", "choice_c": "Is required only if the student is unlicensed", "choice_d": "Is not required if the student is supervised", "correct_choice": "b", "rationale": "The April 2024 CMS guidance explicitly requires informed consent before a medical student performs a sensitive examination, including examinations under anesthesia. Consent to the underlying procedure does not automatically authorize the student''s involvement.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q15", "question_number": 15, "stem": "AANA Standard 3 (Plan for Anesthesia Care) directs the CRNA to develop and document:", "choice_a": "A plan approved by the surgeon before consent is obtained", "choice_b": "A plan that does not include reasonable alternatives", "choice_c": "A patient-specific plan based on the preanesthesia assessment, procedural requirements, and available resources, in collaboration with the patient", "choice_d": "A generic anesthesia plan applicable to all patients", "correct_choice": "c", "rationale": "Standard 3 requires a patient-specific plan developed in collaboration with the patient (and legal representative when indicated). Reasonable alternatives are part of the consent discussion required by Standard 4.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q16", "question_number": 16, "stem": "A Jehovah''s Witness patient signs the anesthesia consent but has a documented advance directive refusing blood products. The CRNA''s most appropriate action is to:", "choice_a": "Ignore the advance directive because consent was signed", "choice_b": "Cancel the case", "choice_c": "Ask the family to override the advance directive", "choice_d": "Verify and document the advance directive per AANA Standard 4 and identify acceptable and unacceptable products in advance", "correct_choice": "d", "rationale": "Standard 4 requires the CRNA to verify, review, or document applicable advance directives and consent for blood products. Acceptable and unacceptable products should be identified in advance and escalated when refusal materially changes risk.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q17", "question_number": 17, "stem": "A patient with dementia is scheduled for cataract surgery under MAC. Regarding consent, the CRNA should:", "choice_a": "Reassess decision-specific capacity, involve the legally authorized representative when required, and document capacity assessment", "choice_b": "Proceed without consent under the emergency exception", "choice_c": "Have the surgeon sign the consent", "choice_d": "Assume the patient can consent because they can state their name", "correct_choice": "a", "rationale": "Capacity is decision-specific and can fluctuate. The CRNA should reassess capacity, involve a legally authorized representative when required, and document the capacity assessment.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q18", "question_number": 18, "stem": "Which of the following statements about CRNA liability and team practice is TRUE?", "choice_a": "The CRNA has no consent responsibility if the anesthesiologist obtained consent", "choice_b": "In every practice model, the CRNA remains responsible for actions within their role, competence, documentation, and communication", "choice_c": "The CRNA''s liability is eliminated by a signed consent form", "choice_d": "The CRNA''s liability is transferred to the anesthesiologist in a medically directed model", "correct_choice": "b", "rationale": "In medically directed, collaborative, independent, and anesthesia-care-team models, each clinician remains responsible for actions within their own role and documentation. Team practice does not eliminate individual CRNA liability.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q19", "question_number": 19, "stem": "For a peripheral nerve block, the anesthesia consent discussion should specifically include which of the following risks?", "choice_a": "Post-dural-puncture headache and high spinal", "choice_b": "Malignant hyperthermia and awareness", "choice_c": "Block failure, incomplete analgesia, bleeding, infection, LAST, nerve injury, and (when anatomically relevant) pneumothorax", "choice_d": "Fetal hypoxia and uterine rupture", "correct_choice": "c", "rationale": "Peripheral nerve block risks are technique-specific: block failure, LAST, nerve injury, and pneumothorax where anatomically relevant. Malignant hyperthermia and awareness relate to general anesthesia; PDPH and high spinal relate to neuraxial techniques.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q20", "question_number": 20, "stem": "A CRNA is caring for a patient in an anesthesia-care-team model. The anesthesiologist obtained consent one day earlier. Before induction, the CRNA should:", "choice_a": "Proceed to induction without further discussion", "choice_b": "Re-obtain consent from the beginning", "choice_c": "Ask the surgeon to re-obtain consent", "choice_d": "Verify that the patient still agrees with the plan, that no major clinical changes have occurred, and that the identity of the practitioner performing the anesthesia has been disclosed", "correct_choice": "d", "rationale": "When consent was obtained earlier by another anesthesia professional, the CRNA should verify continued agreement, absence of major clinical changes, and — per April 2024 CMS guidance — disclosure of the actual practitioner performing the care.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q21", "question_number": 21, "stem": "Which of the following BEST describes the interaction between AANA Standards 2, 3, and 4?", "choice_a": "Standards 2, 3, and 4 establish the sequence of assessment, planning, and consent that the CRNA must complete before delivering care", "choice_b": "Standards 2, 3, and 4 apply only to anesthesiologists", "choice_c": "Standard 4 replaces Standards 2 and 3 for informed consent", "choice_d": "Standards 2 and 3 are optional when Standard 4 is satisfied", "correct_choice": "a", "rationale": "Standards 2, 3, and 4 work together: assess the patient, develop a patient-specific plan, and obtain or verify informed consent before care is delivered.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q22", "question_number": 22, "stem": "A patient signed the anesthesia consent 20 minutes ago and has since received IV midazolam 2 mg. Before proceeding, the CRNA should:", "choice_a": "Cancel the case", "choice_b": "Recognize that sedating medication may impair current capacity and document the consent was completed prior to sedation", "choice_c": "Have the patient re-sign the consent form now", "choice_d": "Assume the previously signed consent remains valid regardless of sedation", "correct_choice": "b", "rationale": "Consent should be obtained before sedating medication impairs capacity. The CRNA should document that consent was completed prior to sedation. Re-signing after sedation does not cure the process problem.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q23", "question_number": 23, "stem": "For an obstetric patient with a labor epidural in place who now requires emergency cesarean delivery under general anesthesia, the CRNA should:", "choice_a": "Rely on the labor-epidural consent alone", "choice_b": "Delay the case for a formal consent discussion regardless of fetal or maternal status", "choice_c": "Recognize that labor-epidural consent does not automatically extend to emergency general anesthesia and, when time permits, obtain additional consent — otherwise document the emergency rationale afterward", "choice_d": "Ask the obstetrician to sign consent on the patient''s behalf", "correct_choice": "c", "rationale": "Labor-epidural consent does not automatically authorize emergency general anesthesia. When time permits, obtain additional consent; when it does not, document the emergency clinical rationale.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q24", "question_number": 24, "stem": "Under 42 CFR §482.24(c)(4)(v), the anesthesia consent form must be:", "choice_a": "Notarized by a hospital attorney", "choice_b": "Signed by two witnesses", "choice_c": "Filed with the state board of nursing", "choice_d": "Properly executed and included in the medical record for procedures specified by medical staff or by federal or state law", "correct_choice": "d", "rationale": "42 CFR §482.24(c)(4)(v) requires properly executed informed-consent forms to be included in the medical record for procedures specified by medical staff or by federal or state law.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_2", "question_id": "course_3_module_2_q25", "question_number": 25, "stem": "A CRNA wants to reduce medico-legal exposure related to anesthesia consent. The single most effective action is to:", "choice_a": "Personally complete the anesthesia consent discussion, individualize risk disclosure, invite questions, and document the discussion — before sedating medications are given", "choice_b": "Use a preprinted risks list without individualizing", "choice_c": "Delegate consent to the preoperative nurse", "choice_d": "Rely on the surgical consent form", "correct_choice": "a", "rationale": "Personal completion of the discussion by the CRNA delivering the care, individualized risk disclosure, and contemporaneous documentation — before sedating medications impair capacity — are the most effective risk-management actions.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module2_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;